import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D3.1 · 设备 agentd 与设备可见性","description":"Hearth D3.1 开发增量：用户能看到一台可信桌面设备上线、具备哪些能力，以及当前是否可执行 GUI 任务。","frontmatter":{"title":"D3.1 · 设备 agentd 与设备可见性","description":"Hearth D3.1 开发增量：用户能看到一台可信桌面设备上线、具备哪些能力，以及当前是否可执行 GUI 任务。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-3/d3-1.md","filePath":"delivery/stage-3/d3-1.md","lastUpdated":null}'),d={name:"delivery/stage-3/d3-1.md"};function r(s,a,o,h,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 3 · D3.1 · 1 / 4</p><h1 id="d3-1-·-设备-agentd-与设备可见性" tabindex="-1">D3.1 · 设备 agentd 与设备可见性 <a class="header-anchor" href="#d3-1-·-设备-agentd-与设备可见性" aria-label="Permalink to &quot;D3.1 · 设备 agentd 与设备可见性&quot;">​</a></h1><p class="lead">先把桌面设备变成一个可识别、可授权、可撤销的执行节点，再谈 GUI 操作。</p><p class="page-meta">STAGE 3 · D3.1 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>用户能看到一台可信桌面设备上线、具备哪些能力，以及当前是否可执行 GUI 任务。</div><div><strong>完成门槛</strong>一台设备可注册、查看和撤销；能力不匹配时任务不分配；设备离线有明确状态；agentd 不能越权访问未声明能力。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>用户能看到一台可信桌面设备上线、具备哪些能力，以及当前是否可执行 GUI 任务。</p><p>Stage 3 的顺序是观察、接管、低风险动作、高风险动作；无法观察和接管的桌面自动化不具备产品资格。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 1–2 的恢复、审批、幂等、回执和网页隔离已经稳定。</li><li>有一台可配对的专用桌面设备，明确哪些窗口、应用和文件范围允许操作。</li><li>GUI 任务可以在隔离桌面中运行，且用户能随时暂停和接管。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-设备配对与持久身份" tabindex="-1">01 · 设备配对与持久身份 <a class="header-anchor" href="#_01-·-设备配对与持久身份" aria-label="Permalink to &quot;01 · 设备配对与持久身份&quot;">​</a></h3><p>用户通过一次性短码或二维码确认配对，设备生成并保存密钥对，服务端只保存公钥、设备 ID 和信任状态。配对会话必须过期、只能使用一次，并在设备详情中显示上次确认时间、agentd 版本和信任来源。</p><h3 id="_02-·-能力声明与最小权限" tabindex="-1">02 · 能力声明与最小权限 <a class="header-anchor" href="#_02-·-能力声明与最小权限" aria-label="Permalink to &quot;02 · 能力声明与最小权限&quot;">​</a></h3><p>agentd 注册时声明可观察的窗口、可操作应用、允许的文件根目录、键鼠能力和敏感能力禁用项。声明经过签名与版本校验，任务请求必须逐项匹配；能力不匹配时拒绝分配并告诉用户缺什么，而不是悄悄降级。</p><h3 id="_03-·-上线状态与设备详情" tabindex="-1">03 · 上线状态与设备详情 <a class="header-anchor" href="#_03-·-上线状态与设备详情" aria-label="Permalink to &quot;03 · 上线状态与设备详情&quot;">​</a></h3><p>建立在线、忙碌、暂停、离线和撤销状态，记录最后心跳、最后同步和当前执行任务。设备页展示能力、最近动作和健康检查；心跳过期自动转为离线，离线设备不接收新的桌面任务。</p><h3 id="_04-·-撤销、任务归属与审计" tabindex="-1">04 · 撤销、任务归属与审计 <a class="header-anchor" href="#_04-·-撤销、任务归属与审计" aria-label="Permalink to &quot;04 · 撤销、任务归属与审计&quot;">​</a></h3><p>撤销设备立即让会话失效、撤回待执行分配，并把正在执行的任务转为需要人工处理。所有配对、能力调用、任务关联和撤销写入审计；验收要证明未声明窗口不可访问、旧会话不可复用、离线状态清晰可见。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/agentd</code> — 设备配对、能力声明、健康检查与撤销</li><li><code>packages/devices</code> — 设备身份、会话、能力目录与在线状态</li><li><code>packages/desktop-observation</code> — 窗口边界、截图、可访问性树与脱敏</li><li><code>packages/desktop-control</code> — 白名单、定位器、输入动作与前后条件</li><li><code>packages/desktop-verification</code> — 截图比较、焦点检查、半完成检测</li><li><code>packages/approval</code> — 桌面 Effect Preview、二次确认与补偿说明</li><li><code>apps/web</code> — 设备页、观察视图、实时接管和恢复界面</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>DeviceManifest</code></td><td>deviceId、publicKey、agentdVersion、capabilities、allowedRoots、expiresAt、revocationState；未声明的能力不可调用。</td></tr><tr><td><code>ObservationFrame</code></td><td>captureId、windowBounds、screenshotRef、accessibilityTree、capturedAt、redactions；只采集完成任务所需的最小范围。</td></tr><tr><td><code>DesktopAction</code></td><td>actionType、targetWindow、locator、preconditions、expectedPostconditions、riskLevel、timeout；执行前必须通过策略检查。</td></tr><tr><td><code>DesktopReceipt</code></td><td>actionId、beforeRef、afterRef、verification、partialState、compensation、approvalId；失败时保留可恢复证据。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:device：配对、能力越权、离线、撤销和会话失效</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:desktop：观察、接管、焦点变化、半完成和补偿</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:desktop-fault：窗口漂移、元素消失、输入争抢和崩溃</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:computer：至少</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 个真实桌面任务及失败样本</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-3/d3-1.html">D3.1 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：设备配对与持久身份、能力声明与最小权限、上线状态与设备详情、撤销、任务归属与审计。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“窗口或元素不匹配”。页面必须显示“任务暂停并显示当前窗口截图和需要确认的元素。”，然后按“重新定位、请求接管或调整白名单，不盲目点击坐标。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：一台设备可注册、查看和撤销；能力不匹配时任务不分配；设备离线有明确状态；agentd 不能越权访问未声明能力。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>设备配对流程</li><li>能力目录与设备详情</li><li>断开/撤销演示</li><li>未声明能力访问测试</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 一台设备可注册、查看和撤销；能力不匹配时任务不分配；设备离线有明确状态；agentd 不能越权访问未声明能力。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>窗口或元素不匹配</td><td>任务暂停并显示当前窗口截图和需要确认的元素。</td><td>重新定位、请求接管或调整白名单，不盲目点击坐标。</td></tr><tr><td>自动输入与用户争抢</td><td>自动输入立即暂停，控制权交给用户。</td><td>等待用户交还并确认焦点、窗口和下一步。</td></tr><tr><td>高风险动作半完成</td><td>任务显示“需要检查”，隐藏继续按钮并保留快照。</td><td>按补偿脚本或人工接管恢复，记录未完成影响。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不在无法观察、无法验证或无法接管时开放自动操作。</li><li>不读取密码库，不修改系统安全设置，不操作未授权窗口。</li><li>不把一次成功的坐标点击当成通用 GUI 能力。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/human-takeover.html">人工接管与审批</a></li><li><a href="/hearth-os/architecture/execution-safety.html">执行安全与副作用</a></li><li><a href="/hearth-os/architecture/executor-catalog.html">执行器目录</a></li><li><a href="/hearth-os/architecture/frontend-experience.html">前端与移动体验</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-3/d3-2.html">D3.2 · GUI 观察与人工接管</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const k=e(d,[["render",r]]);export{u as __pageData,k as default};
